<?php declare(strict_types=1);$title='Clientes';require BASE_PATH.'/app/Views/admin/_top.php';?>
<section class="page-heading"><div><p class="eyebrow">Cadastro compartilhado</p><h1>Clientes</h1><p><?= (int)$result['total'] ?> cliente(s) sem duplicação por telefone normalizado.</p></div></section>
<form class="filter-bar customer-filter" method="get" action="<?= e(base_url('admin/clientes')) ?>"><input name="q" value="<?= e($q) ?>" placeholder="Nome, e-mail ou telefone"><button class="admin-primary">Buscar</button></form>
<section class="admin-panel"><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Contato</th><th>Reservas</th><th>Última reserva</th><th>Status</th></tr></thead><tbody><?php foreach($result['items']as$c):?><tr data-href="<?= e(base_url('admin/clientes/'.$c['id'])) ?>"><td><a href="<?= e(base_url('admin/clientes/'.$c['id'])) ?>"><strong><?= e($c['nome']) ?></strong></a></td><td><?= e($c['email']?:'—') ?><small><?= e($c['telefone_normalizado']?:'—') ?></small></td><td><?= (int)$c['total_reservas'] ?></td><td><?= e($c['ultima_reserva_em']?date('d/m/Y',strtotime($c['ultima_reserva_em'])):'—') ?></td><td><?= e($c['status']) ?></td></tr><?php endforeach;?></tbody></table></div></section>
